import boto3
import os
import json

def upsert_document(table_name: str, document_id: str, document: dict) -> dict:
    """
    Upserts a JSON document by its primary identifier into an Amazon DynamoDB table.

    Args:
        table_name: The name of the DynamoDB table.
        document_id: The primary identifier of the document.
        document: The JSON document to upsert.

    Returns:
        The response from the DynamoDB put_item operation.
    """
    # Initialize DynamoDB client
    # AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, AWS_SESSION_TOKEN (optional), and AWS_REGION
    # are typically loaded from environment variables or ~/.aws/credentials
    dynamodb = boto3.client('dynamodb')

    # Add the document_id to the document as the primary key
    # Assuming 'id' is the primary key attribute name
    item_to_put = {"id": document_id, **document}

    # Convert Python dict to DynamoDB item format (e.g., {"S": "value"}, {"N": "123"})
    # This is a simplified conversion, for complex types or nested objects, a more
    # robust serialization function would be needed.
    dynamodb_item = {}
    for key, value in item_to_put.items():
        if isinstance(value, str):
            dynamodb_item[key] = {'S': value}
        elif isinstance(value, (int, float)):
            dynamodb_item[key] = {'N': str(value)}
        elif isinstance(value, bool):
            dynamodb_item[key] = {'BOOL': value}
        elif isinstance(value, dict) or isinstance(value, list):
            # For complex types, convert to JSON string
            dynamodb_item[key] = {'S': json.dumps(value)}
        else:
            # Handle other types or skip
            pass

    response = dynamodb.put_item(
        TableName=table_name,
        Item=dynamodb_item
    )
    return response
